/*
 * win_$sense_general_status - turn the drive's general status byte into a
 * disk status, reading the ANSI status registers it points at
 *
 * Original address: 0x00E19186 (module-local; the SAU2 map has no symbol
 * here; was Ghidra FUN_00e19186)
 * Size: 240 bytes (0x00E19186 .. 0x00E19275)
 * Generated by: Claude Opus 5.5
 *
 * Only caller: WIN_$CHECK_DISK_STATUS (0x00E19378).  Uses its caller's
 * A5 = 0xE2B89C (WIN_$DATA): (0x70,A5) / (0x71,A5) receive the two ANSI
 * report bytes (cleared together by `clr.w (0x70,A5)`), (0x4c,A5) and
 * (0x4e,A5) are statistics words.  No result slot: the status is D0.
 *
 * Frame (link.w A6,-0x14): (0x8,A6) unit word, (0xa,A6) the general status
 * BYTE, (0xc,A6) out (A2); (-0x12,A6) an uninitialised word passed as the
 * ANSI input parameter (both commands are < 0x40, so it is never read).
 *
 * Blocks:
 *   0x00E1918E-0x00E191A2  status & 0x30 == 0 -> *out = 0, return 0
 *   0x00E191A6-0x00E191AA  clear both report bytes; D2 = 0
 *   0x00E191AC-0x00E19210  bit 4: *out = 1; ANSI 0x0E into +0x70; on success
 *                          bit 0 -> +0x4C++, seek error; bit 3 -> write
 *                          protected; & 0x36 -> +0x4E++, equipment check;
 *                          else unknown status
 *   0x00E19216-0x00E19260  D0 = 0; bit 5: *out = 2; ANSI 0x0D into +0x71;
 *                          on success bit 1 with general bit 0 -> not
 *                          ready; else bit 0 clear -> unknown status
 *   0x00E19266-0x00E1926A  a bit-4 status wins over the bit-5 one
 */

#include "win/win_internal.h"

/* (0x70,A5) and (0x71,A5): the two ANSI report bytes */
#define WIN_SENSE_REPORT_A   0x70
#define WIN_SENSE_REPORT_B   0x71
/* (0x4c,A5) and (0x4e,A5): the seek-error and equipment-check counts */
#define WIN_SEEK_ERROR_COUNT  (*(uint16_t *)(WIN_DATA_BASE + 0x4C))
#define WIN_EQUIP_CHECK_COUNT (*(uint16_t *)(WIN_DATA_BASE + 0x4E))

status_$t win_$sense_general_status(uint16_t unit, uint8_t general_status,
                                    uint16_t *out)
{
    status_$t result;       /* D0 */
    status_$t first;        /* D2 */
    char in_param[2];       /* (-0x12,A6), never written */
    uint8_t *report_a = &WIN_DATA_BASE[WIN_SENSE_REPORT_A];
    uint8_t *report_b = &WIN_DATA_BASE[WIN_SENSE_REPORT_B];

    /* 0x00E1918E-0x00E191A2 */
    if ((general_status & 0x30) == 0) {
        *out = 0;
        return status_$ok;
    }

    /* 0x00E191A6-0x00E191AA */
    *report_a = 0;
    *report_b = 0;
    first = status_$ok;

    /* 0x00E191AC-0x00E19210 */
    if ((general_status & 0x10) != 0) {
        *out = 1;
        first = WIN_$ANSI_COMMAND(unit, 0x0E, in_param, (char *)report_a);
        if (first == status_$ok) {
            if ((*report_a & 0x01) != 0) {
                WIN_SEEK_ERROR_COUNT++;                 /* 0x00E191DC */
                first = status_$disk_seek_error;
            } else if ((*report_a & 0x08) != 0) {
                first = status_$disk_write_protected;   /* 0x00E191F0 */
            } else if ((*report_a & 0x36) != 0) {
                WIN_EQUIP_CHECK_COUNT++;                /* 0x00E19204 */
                first = status_$disk_equipment_check;
            } else {
                first = status_$unknown_error_status_from_drive;
            }
        }
    }

    /* 0x00E19216-0x00E19260 */
    result = status_$ok;
    if ((general_status & 0x20) != 0) {
        *out = 2;
        result = WIN_$ANSI_COMMAND(unit, 0x0D, in_param, (char *)report_b);
        if (result == status_$ok) {
            if ((*report_b & 0x02) != 0 && (general_status & 0x01) != 0) {
                result = status_$disk_not_ready;        /* 0x00E19250 */
            } else if ((*report_b & 0x01) == 0) {
                result = status_$unknown_error_status_from_drive;
            }
        }
    }

    /* 0x00E19266-0x00E1926A */
    if (first != status_$ok) {
        result = first;
    }
    return result;
}
